```{.python .cell-code}
# Import necessary libraries
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from sklearn.model_selection import train_test_split
from sklearn.linear_model import LinearRegression
from sklearn.metrics import mean_squared_error
```
:::




::: {.cell}

```{.python .cell-code}
# Set seed for reproducibility
np.random.seed(42)
```
:::




::: {.cell}

```{.python .cell-code}
# Generate initial healthcare data
age = np.random.normal(60, 15, 1000)  # Patient age
severity = np.random.uniform(1, 10, 1000)  # Illness severity score (1-10)
noise = np.random.normal(0, 2, 1000)  # Random noise
LOS = 0.5 * age + 2 * severity + noise  # Linear relationship - normally would not have this! THis is what we are trying to find out!

# Create a DataFrame
data = pd.DataFrame({'Age': age, 'Severity': severity, 'LOS': LOS})
```
:::




::: {.cell}

```{.python .cell-code}
# Split data into training and test sets
train, test = train_test_split(data, test_size=0.2, random_state=42)
```
:::




::: {.cell}

```{.python .cell-code}
# Define and fit a linear regression model
model = LinearRegression()
model.fit(train[['Age', 'Severity']], train['LOS'])
```

